private void xrTableCell12_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
var parametraRaporti = AlphaWebReports.raporteUtil.DeserializoParametraPerKonstruktorRaporti(this.Extensions["parametraRaporti"]);
if (GetCurrentColumnValue("VLERA") != null)
            {
                string vlera = String.Format("{0:#,#.00}", GetCurrentColumnValue("VLERA"));
                if (Convert.ToDouble(vlera) > 1)
                   xrTableCell12.Text =  AlphaWebReports.NumberConverter.changeToWords(vlera, parametraRaporti.Ci);    
        }
}

