private void Rap_MandatArketimPagese_Model6_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {

            this.Detail.Controls.Add(CreateXRTable());
            System.Data.DataTable dt = ((System.Data.DataSet)(this.DataSource)).Tables[0];
        trupi.Clear();
            for (int i = 0; i < dt.Rows.Count; i++)
            {
                object pershkrimiTrupi = dt.Rows[i]["PERSHKRIMITRUPI"];
                object vleraPaguar = dt.Rows[i]["VLERAPAGUAR"];
                object kodSubjekti = dt.Rows[i]["kodSubjekti"];
                object emertimSubjekti = dt.Rows[i]["emertimSubjekti"];
                object[] obj = new object[3];
                obj[0] = kodSubjekti + " (" + emertimSubjekti + " )";
                obj[1] = pershkrimiTrupi;
                obj[2] = vleraPaguar;
                trupi.Add(obj);
            }
}
     private XRTable CreateXRTable()
        {
            int i = 0;
            XRTable table = new XRTable();
            table.Size = new Size(650, 25);
            table.BeginInit();
             var parametraRaporti = AlphaWebReports.raporteUtil.DeserializoParametraPerKonstruktorRaporti(this.Extensions["parametraRaporti"]);

            table.LocationF = new DevExpress.Utils.PointFloat(0F, 0F);
            if (trupi.Count > 0)
            {
                for (int j = table.Rows.Count - 1; j >= 2; j--)
                {
                    table.Rows.RemoveAt(j);
                }

                foreach (object[] obj in trupi)
                {
                    XRTableRow rr = new XRTableRow();
                    rr.HeightF = 25f;

                    XRTableCell lbl = new XRTableCell();
                    lbl.WidthF = 25.21f;
                    lbl.Name = "lbl" ;//+ i.ToString();
                    lbl.Text = "";
                    lbl.Borders = DevExpress.XtraPrinting.BorderSide.Top | DevExpress.XtraPrinting.BorderSide.Left;
                    rr.Cells.Add(lbl);

                    XRTableCell lblPer = new XRTableCell();
                    lblPer.WidthF = 102.19f;
                    lblPer.Name = "lblPer"; //+ i.ToString();
                    lblPer.Font = new System.Drawing.Font("Times New Roman", 9.75F, System.Drawing.FontStyle.Bold);
                    lblPer.Text = rm.GetString("labelRaportPer", parametraRaporti.Ci);
                    lblPer.TextAlignment = DevExpress.XtraPrinting.TextAlignment.MiddleLeft;
                    lblPer.Borders = DevExpress.XtraPrinting.BorderSide.Top;
                    rr.Cells.Add(lblPer);

                    XRTableCell pershkrimi = new XRTableCell();
                    pershkrimi.WidthF = 343.85f;
                 pershkrimi.Name = "pershkrimi";// + i.ToString();
                    pershkrimi.Text = obj[0].ToString();
                    pershkrimi.TextAlignment = DevExpress.XtraPrinting.TextAlignment.MiddleLeft;
                    pershkrimi.Font = new System.Drawing.Font("Times New Roman", 9.75F, System.Drawing.FontStyle.Regular);
                    pershkrimi.Borders = DevExpress.XtraPrinting.BorderSide.Top | DevExpress.XtraPrinting.BorderSide.Right;
                    rr.Cells.Add(pershkrimi);

                    XRTableCell lblShuma = new XRTableCell();
                    lblShuma.WidthF = 63.12f;
                   lblShuma.Name = "lblShuma" ;//+ i.ToString();
                    lblShuma.Font = new System.Drawing.Font("Times New Roman", 9.75F, System.Drawing.FontStyle.Italic);
                    lblShuma.TextAlignment = DevExpress.XtraPrinting.TextAlignment.MiddleLeft;
                    lblShuma.Text =   rm.GetString("labelRaportiShuma", parametraRaporti.Ci) + ":";
                    lblShuma.Borders = DevExpress.XtraPrinting.BorderSide.Top | DevExpress.XtraPrinting.BorderSide.Left | DevExpress.XtraPrinting.BorderSide.Bottom;
                    rr.Cells.Add(lblShuma);

                    XRTableCell vleraPaguar = new XRTableCell();
                    vleraPaguar.WidthF = 115.62f;
                  vleraPaguar.Name = "vleraPaguar";// + i.ToString();
                    vleraPaguar.Text = String.Format("{0:#,#.00}", obj[1]);
                    vleraPaguar.TextAlignment = DevExpress.XtraPrinting.TextAlignment.MiddleRight;
                    vleraPaguar.Padding = new DevExpress.XtraPrinting.PaddingInfo(7, 7, 0, 0);
                    vleraPaguar.Font = new System.Drawing.Font("Times New Roman", 9.75F, System.Drawing.FontStyle.Regular);
                    vleraPaguar.Borders = DevExpress.XtraPrinting.BorderSide.Bottom | DevExpress.XtraPrinting.BorderSide.Top | DevExpress.XtraPrinting.BorderSide.Right;
                    rr.Cells.Add(vleraPaguar);
                    table.Rows.Add(rr);
                    i++;
                }
                table.EndInit();
            }
            return table;
        }

private void xrTable2_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
shtoRreshtatNeTabele(xrTable2);
}

private void xrTable6_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
 shtoRreshtatNeTabele(xrTable6);
}

   private void shtoRreshtatNeTabele(XRTable xrTable2)
        {
            int i = 0;
            if (trupi.Count > 0)
            {
                for (int j = xrTable2.Rows.Count - 1; j >= 2; j--)
                {
                    xrTable2.Rows.RemoveAt(j);
                }
                foreach (object[] obj in trupi)
                {
                    XRTableRow rr = new XRTableRow();
                    rr.HeightF = 25f;
             var parametraRaporti = AlphaWebReports.raporteUtil.DeserializoParametraPerKonstruktorRaporti(this.Extensions["parametraRaporti"]);


                    XRTableCell lblPer = new XRTableCell();
                    lblPer.WidthF = 52.08f;
                   // lblPer.Name = "lblPer" + i.ToString();
                    lblPer.Font = new System.Drawing.Font("Times New Roman", 9.75F, System.Drawing.FontStyle.Bold);
                    lblPer.Text = rm.GetString("labelRaportPer", parametraRaporti.Ci);
                    lblPer.TextAlignment = DevExpress.XtraPrinting.TextAlignment.MiddleLeft;
                    lblPer.Borders = DevExpress.XtraPrinting.BorderSide.Top | DevExpress.XtraPrinting.BorderSide.Left; 
                    rr.Cells.Add(lblPer);

                    XRTableCell pershkrimi = new XRTableCell();
                    pershkrimi.WidthF =454.02f;
                   // pershkrimi.Name = "pershkrimi" + i.ToString();
                    pershkrimi.Text = obj[1].ToString();
                    pershkrimi.Padding = new DevExpress.XtraPrinting.PaddingInfo(0, 4, 0, 0);
                    pershkrimi.TextAlignment = DevExpress.XtraPrinting.TextAlignment.MiddleLeft;
                    pershkrimi.Font = new System.Drawing.Font("Times New Roman", 9.75F, System.Drawing.FontStyle.Regular);
                    pershkrimi.Borders = DevExpress.XtraPrinting.BorderSide.Top | DevExpress.XtraPrinting.BorderSide.Right;
                    rr.Cells.Add(pershkrimi);

                    XRTableCell lblShuma = new XRTableCell();
                    lblShuma.WidthF = 96.87f;
                   // lblShuma.Name = "lblShuma" + i.ToString();
                    lblShuma.Font = new System.Drawing.Font("Times New Roman", 9.75F, System.Drawing.FontStyle.Italic);
                    lblShuma.TextAlignment = DevExpress.XtraPrinting.TextAlignment.MiddleLeft;
                    lblShuma.Text =  rm.GetString("labelRaportiShuma", parametraRaporti.Ci) + ":";
                    lblShuma.Borders = DevExpress.XtraPrinting.BorderSide.Top | DevExpress.XtraPrinting.BorderSide.Left | DevExpress.XtraPrinting.BorderSide.Bottom;
                    rr.Cells.Add(lblShuma);

                    XRTableCell vleraPaguar = new XRTableCell();
                    vleraPaguar.WidthF = 95.08f;
                   // vleraPaguar.Name = "vleraPaguar" + i.ToString();
                    vleraPaguar.Text = String.Format("{0:#,#.00}", obj[2]);
                    vleraPaguar.TextAlignment = DevExpress.XtraPrinting.TextAlignment.MiddleRight;
                    vleraPaguar.Padding = new DevExpress.XtraPrinting.PaddingInfo(7, 7, 0, 0);
                    vleraPaguar.Font = new System.Drawing.Font("Times New Roman", 9.75F, System.Drawing.FontStyle.Regular);
                    vleraPaguar.Borders = DevExpress.XtraPrinting.BorderSide.Bottom | DevExpress.XtraPrinting.BorderSide.Top | DevExpress.XtraPrinting.BorderSide.Right;
                    rr.Cells.Add(vleraPaguar);
                    xrTable2.Rows.Insert((i + 2), rr);
                    i++;
                }
            }
        }
